import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  TextInput,
  ScrollView,
  Platform,
} from 'react-native';
import { useAuth, USER_PROFILES } from '../context/AuthContext';

export default function LoginScreen() {
  const { loginAs } = useAuth();
  const [selectedRole, setSelectedRole] = useState('admin');
  const [email, setEmail] = useState('admin@saferide.edu');
  const [password, setPassword] = useState('••••••••••••');
  const [biometricScanning, setBiometricScanning] = useState(false);

  const handleRoleSelect = (roleKey) => {
    setSelectedRole(roleKey);
    const profile = USER_PROFILES[roleKey];
    if (profile) {
      setEmail(profile.email);
      setPassword('securePass@2026');
    }
  };

  const handleLogin = () => {
    loginAs(selectedRole);
  };

  const handleBiometricSim = () => {
    setBiometricScanning(true);
    setTimeout(() => {
      setBiometricScanning(false);
      loginAs(selectedRole);
    }, 1000);
  };

  return (
    <View style={styles.container}>
      <ScrollView contentContainerStyle={styles.scrollContent}>
        {/* Top Header Badge */}
        <View style={styles.topStatusBadge}>
          <View style={styles.greenPulseDot} />
          <Text style={styles.topStatusText}>
            QUANTUM-SECURED FLEET DISPATCH MATRIX • V2.4-PROD
          </Text>
        </View>

        {/* Hero Branding */}
        <View style={styles.brandHero}>
          <View style={styles.logoHalo}>
            <Text style={styles.heroLogoEmoji}>🛡️</Text>
          </View>
          <View style={styles.brandTitleContainer}>
            <Text style={styles.heroTitle}>SafeRide</Text>
            <Text style={styles.heroTitleAccent}>+ Enterprise</Text>
          </View>
          <Text style={styles.heroSubtitle}>
            AI-Driven Autonomous School Bus Telemetry & Biometric Safe-Drop Verification
          </Text>
        </View>

        {/* Role Selector Deck */}
        <View style={styles.deckCard}>
          <Text style={styles.sectionHeader}>SELECT ACCESS PERSPECTIVE</Text>
          <Text style={styles.sectionSub}>
            Choose a persona to immediately access dedicated mission consoles:
          </Text>

          <View style={styles.roleGrid}>
            {Object.keys(USER_PROFILES).map((key) => {
              const p = USER_PROFILES[key];
              const isSelected = selectedRole === key;
              return (
                <TouchableOpacity
                  key={key}
                  style={[styles.roleCard, isSelected && styles.roleCardActive]}
                  onPress={() => handleRoleSelect(key)}
                  activeOpacity={0.7}
                >
                  <View style={styles.roleCardTop}>
                    <Text style={styles.roleCardEmoji}>{p.avatar}</Text>
                    {isSelected && <View style={styles.selectedPill}><Text style={styles.selectedPillText}>READY</Text></View>}
                  </View>
                  <Text style={[styles.roleCardTitle, isSelected && styles.roleCardTitleActive]}>
                    {p.roleTitle}
                  </Text>
                  <Text style={styles.roleCardName}>{p.name}</Text>
                  <Text style={styles.roleCardDesc}>
                    {key === 'admin' && 'Fleet grid, live map radar & SOS emergency dispatch'}
                    {key === 'driver' && 'Cockpit terminal, manifest & tap-to-scan RFID engine'}
                    {key === 'parent' && 'Live child journey tracking, geofence audit & ETA radar'}
                    {key === 'student' && 'Digital RFID pass, route stops & emergency guide'}
                  </Text>
                </TouchableOpacity>
              );
            })}
          </View>
        </View>

        {/* Authentication Card */}
        <View style={styles.authCard}>
          <View style={styles.authCardHeader}>
            <Text style={styles.authCardTitle}>Mission Authorization</Text>
            <Text style={styles.authCardBadge}>{USER_PROFILES[selectedRole].roleTitle}</Text>
          </View>

          <View style={styles.fieldGroup}>
            <Text style={styles.fieldLabel}>OPERATOR IDENTITY / EMAIL</Text>
            <TextInput
              style={styles.textInput}
              value={email}
              onChangeText={setEmail}
              placeholder="operator@saferide.edu"
              placeholderTextColor="#64748b"
              autoCapitalize="none"
            />
          </View>

          <View style={styles.fieldGroup}>
            <View style={styles.passwordLabelRow}>
              <Text style={styles.fieldLabel}>ENCRYPTED ACCESS KEY</Text>
              <Text style={styles.forgotPass}>Request Security Reset</Text>
            </View>
            <TextInput
              style={styles.textInput}
              value={password}
              onChangeText={setPassword}
              secureTextEntry
              placeholder="••••••••••••"
              placeholderTextColor="#64748b"
            />
          </View>

          <View style={styles.securityMetaRow}>
            <Text style={styles.securityMetaText}>🔒 256-Bit Hardware Token: ACTIVE</Text>
            <Text style={styles.securityMetaText}>📍 Geo-Boundary: IN BOUNDS</Text>
          </View>

          {/* Action Buttons */}
          <TouchableOpacity
            style={styles.primaryAuthBtn}
            onPress={handleLogin}
            activeOpacity={0.85}
          >
            <Text style={styles.primaryAuthBtnText}>
              Launch {USER_PROFILES[selectedRole].roleTitle} Portal →
            </Text>
          </TouchableOpacity>

          <TouchableOpacity
            style={[styles.biometricBtn, biometricScanning && styles.biometricBtnScanning]}
            onPress={handleBiometricSim}
            activeOpacity={0.8}
          >
            <Text style={styles.biometricIcon}>
              {biometricScanning ? '⚡' : '👁️'}
            </Text>
            <Text style={styles.biometricText}>
              {biometricScanning
                ? 'Validating Biometric Telemetry & RFID Tag...'
                : 'Instant Biometric / RFID Quick-Login'}
            </Text>
          </TouchableOpacity>
        </View>

        {/* Live System Metrics Footer */}
        <View style={styles.systemMetricsRow}>
          <View style={styles.metricItem}>
            <Text style={styles.metricVal}>4 / 4</Text>
            <Text style={styles.metricKey}>Fleet Online</Text>
          </View>
          <View style={styles.metricDivider} />
          <View style={styles.metricItem}>
            <Text style={styles.metricVal}>100%</Text>
            <Text style={styles.metricKey}>Geofence Shield</Text>
          </View>
          <View style={styles.metricDivider} />
          <View style={styles.metricItem}>
            <Text style={styles.metricVal}>0.04s</Text>
            <Text style={styles.metricKey}>Telemetry Sync</Text>
          </View>
          <View style={styles.metricDivider} />
          <View style={styles.metricItem}>
            <Text style={styles.metricVal}>99.98%</Text>
            <Text style={styles.metricKey}>Safety Index</Text>
          </View>
        </View>
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#FFF9F5', // Warm clean white canvas
    ...Platform.select({
      web: { height: '100vh', overflowY: 'auto' },
    }),
  },
  scrollContent: {
    padding: 24,
    alignItems: 'center',
    maxWidth: 960,
    alignSelf: 'center',
    width: '100%',
  },
  topStatusBadge: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 8,
    backgroundColor: '#FFF1F2',
    borderWidth: 1.5,
    borderColor: '#FECACA',
    paddingHorizontal: 14,
    paddingVertical: 6,
    borderRadius: 20,
    marginTop: 10,
    marginBottom: 20,
  },
  greenPulseDot: {
