    backgroundColor: '#FF6B00',
  },
  topStatusText: {
    color: '#DC2626',
    fontSize: 10,
    fontWeight: '900',
    letterSpacing: 1,
  },
  brandHero: {
    alignItems: 'center',
    marginBottom: 26,
  },
  logoHalo: {
    width: 72,
    height: 72,
    borderRadius: 24,
    backgroundColor: '#FFFFFF',
    borderWidth: 2.5,
    borderColor: '#DC2626',
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 14,
