    fontSize: 36,
  },
  brandTitleContainer: {
    flexDirection: 'row',
    alignItems: 'baseline',
    gap: 6,
  },
  heroTitle: {
    fontSize: 38,
    fontWeight: '900',
    color: '#DC2626',
    letterSpacing: -1,
  },
  heroTitleAccent: {
    fontSize: 38,
    fontWeight: '900',
    color: '#FF6B00',
    letterSpacing: -1,
  },
  heroSubtitle: {
    color: '#64748B',
    fontSize: 14,
    textAlign: 'center',
    marginTop: 8,
    maxWidth: 580,
    lineHeight: 20,
    fontWeight: '500',
  },
  deckCard: {
    width: '100%',
    backgroundColor: '#FFFFFF',
